+      // estimation basis (Σ chars) stays truthful.
+      for (var i = 0; i < stripped.messages.length; i++) {
+        expect(stripped.messages[i].role, detail.messages[i].role);
+        expect(stripped.messages[i].chars, detail.messages[i].chars);
