+  });
+
+  group('TrajectoryRequestBlobStore', () {
+    late MemoryExecutionEnv env;
+
+    setUp(() => env = MemoryExecutionEnv(cwd: '/work'));
+
+    TrajectoryRequestBlobStore store({
+      String? Function()? sessionId,
