  final manifestHash = detail.toolManifestHash;
  if (manifestHash != null) {
    final blob = blobs.toolManifests[manifestHash];
    _inspectSection(
      lines,
      'manifest',
      blob == null
          ? manifestHash
          : '$manifestHash · ${blob.tools.length} tools',
    );
  }
  final wireHash = detail.wireDumpHash;
  if (wireHash != null) {
    final dump = blobs.wireDumps[wireHash];
    _inspectSection(
      lines,
      'wire dump',
      dump == null
          ? wireHash
          : '$wireHash · ${dump.payload.length} chars${dump.truncated ? ' · truncated' : ''}',
    );
  }
  // gh-1745: the heavy detail (per-message texts, the raw dump) lives in
  // the session's request-blob dir; the pointer names the file.
  final spillFile = detail.spillFile;
  if (spillFile != null) {
    _inspectSection(lines, 'request blob', spillFile);
  }
}

