  // gh-1745: the heavy detail (per-message texts, the raw dump) lives in
  // the session's request-blob dir; the pointer names the file.
  final spillFile = detail.spillFile;
  if (spillFile != null) {
    _inspectSection(lines, 'request blob', spillFile);
  }
}

